def p(s): return '<p>'+s+'</p>'
def ul(*items): return '<ul>'+''.join('<li>'+i+'</li>' for i in items)+'</ul>'
def flow(*items): return '<div class="flow" aria-label="Conceptual workflow">'+''.join(f'<div><span>0{i+1}</span>{x}</div>' for i,x in enumerate(items))+'</div>'
def table(headers,rows): return '<div class="table-wrap"><table><thead><tr>'+''.join('<th scope="col">'+h+'</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join('<td>'+v+'</td>' for v in row)+'</tr>' for row in rows)+'</tbody></table></div>'

