def head(title,description,path,prefix=''):
    return f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{E(title)} | Hamza Ouriour</title><meta name="description" content="{E(description)}"><meta property="og:title" content="{E(title)} | Hamza Ouriour"><meta property="og:description" content="{E(description)}"><meta property="og:type" content="website"><meta property="og:url" content="{BASE+path}"><link rel="canonical" href="{BASE+path}"><meta name="theme-color" content="#142b3e"><link rel="icon" href="{prefix}favicon.svg" type="image/svg+xml"><link rel="stylesheet" href="{prefix}styles.css"><script defer src="{prefix}site.js"></script></head><body><a class="skip" href="#main">Skip to content</a>'''

def nav(prefix=''):
    return f'''<header><nav class="nav wrap" aria-label="Main navigation"><a class="brand" href="{prefix}index.html"><span class="monogram" aria-hidden="true">HO</span>Hamza Ouriour</a><button class="menu-toggle" aria-controls="navigation" aria-expanded="false">Menu</button><div class="nav-links" id="navigation"><a href="{prefix}index.html#projects">Projects</a><a href="{prefix}index.html#experience">Experience</a><a href="{prefix}index.html#skills">Skills</a><a href="{prefix}index.html#about">About</a><a href="{prefix}index.html#contact">Contact</a><a href="{prefix}Hamza_Ouriour_Resume.pdf">Résumé ↗</a></div></nav></header>'''

def footer(prefix=''):
    return f'''<footer><div class="wrap"><span>© 2026 Hamza Ouriour · Boston, MA</span><a href="{prefix}index.html#contact">Mechanical systems. Measured decisions.</a></div></footer></body></html>'''

def metrics(values):
    return '<div class="metrics">'+''.join(f'<div class="metric"><strong>{E(n)}</strong><span>{E(l)}</span></div>' for n,l in values)+'</div>'

def card(d):
    return f'''<article class="project-card" data-category="{d['category']}"><div class="card-visual"><strong>{E(d['metric'])}</strong><span>{E(d['metric_label'])}</span></div><div class="card-body"><p class="eyebrow">{d['kind']}</p><h3><a href="projects/{d['slug']}.html">{d['title']}</a></h3><p>{d['summary']}</p><div class="card-bottom"><span>{d['category'].replace(' ', ' / ').title()}</span><a href="projects/{d['slug']}.html" aria-label="Read case study: {E(d['title'])}">Case study ↗</a></div></div></article>'''

